// 某个页面能看到的记录：去掉别的页面专属的条目，空了的版本不显示
function changelogFor(page) {
  return CHANGELOG.map(x => ({ v: x.v, d: x.d, items: (!x.p || x.p === page) ? x.items.map(it => typeof it === "string" ? it : (!it.p || it.p === page) ? it.t : null).filter(Boolean) : [] }))
    .filter(x => x.items.length);
}
// 设置页最下面的“版本”卡片
function changelogCard(wrap, page) {
  const list = changelogFor(page), now = list[0];
  const card = setSection(wrap, "版本", `当前版本 v${now.v} · ${now.d} 更新`);
  card.classList.add("cl-card");
  const d = el("details", "cl-fold");
  const s = el("summary", null, `查看更新记录（共 ${list.length} 个版本）`);
  d.append(s);
  list.forEach((x, index) => {
    const box = el("div", "cl-ver");
    const h = el("div", "cl-head"); h.append(el("b", null, "v" + x.v), el("span", "cl-date", x.d));
    const ul = el("ul");
    const french = typeof UI_LANG !== "undefined" && UI_LANG === "fr";
    if (french && index >= 10) { ul.dataset.noi18n = ""; ul.dataset.i18nArchive = ""; }
    x.items.forEach(t => ul.append(el("li", null, french && index < 10 ? tr(t) : t)));
    box.append(h, ul); d.append(box);
  });
  card.append(d);
  return card;
}

